mapper.select:
SELECT outcome, screen_time AS screenTime, screen_order FROM tb_screen_collect WHERE person_id = #{personId}
AND `year` = #{year}
AND `screen_type` = #{screenType}
ORDER BY screen_order DESC LIMIT 1

select sc.*,sp.screen_point,sp.name
from tb_screen_collect sc
left join tb_screen_person sp on sc.person_id = sp.id
where sp.screen_point=#{screenPoint}
and sc.year=#{year}

    and sc.screen_id like concat('%',#{screenId},'%')

and sc.deleted=0
and sp.deleted=0
order by sc.id desc

    limit #{pageNo},#{pageSize}

select ifnull(count(*),0) from tb_screen_collect sc left join tb_screen_person sp on sc.person_id = sp.id where sp.screen_point=#{screenPoint} and sc.year=#{year}
and sc.screen_id like concat('%',#{screenId},'%')
and sc.deleted=0 and sp.deleted=0
